package crypto

import (
	"testing"
)

// TestDecrypt_PHPFixture validates against a ciphertext generated by real
// PHP: openssl_encrypt(json_encode($data), 'AES-256-CBC', $key, OPENSSL_RAW_DATA, $iv)
// then urlencode(base64_encode($encrypted)) — the exact pattern a PHP sender
// uses (see the PHP snippet in the sample integration doc).
func TestDecrypt_PHPFixture(t *testing.T) {
	key := []byte("abcdefghij0123456789ABCDEFGHIJ01")
	iv := []byte("0123456789abcdef")
	encoded := `Pg4wTjo%2BdxDRpCMwY6BgouDN4i77b1sPZwWqLiNVhk8lBg3KybTB%2B400uKQKhpsy5usqOsVRGNh57bfeCkMDHw%3D%3D`
	wantPlaintext := `{"order_id":"PO-1029","amount":4599.5,"items":["a","b","c"]}`

	got, err := Decrypt(encoded, key, iv)
	if err != nil {
		t.Fatalf("Decrypt returned error: %v", err)
	}
	if string(got) != wantPlaintext {
		t.Fatalf("Decrypt mismatch:\n got:  %s\n want: %s", got, wantPlaintext)
	}
}

func TestEncryptDecryptRoundTrip(t *testing.T) {
	key := []byte("01234567890123456789012345678901") // 32 bytes… trimmed below
	key = key[:KeySize]
	iv := []byte("abcdefghijklmnop")[:IVSize]
	plaintext := []byte(`{"hello":"world","n":42}`)

	encoded, err := Encrypt(plaintext, key, iv)
	if err != nil {
		t.Fatalf("Encrypt returned error: %v", err)
	}

	got, err := Decrypt(encoded, key, iv)
	if err != nil {
		t.Fatalf("Decrypt returned error: %v", err)
	}
	if string(got) != string(plaintext) {
		t.Fatalf("round trip mismatch:\n got:  %s\n want: %s", got, plaintext)
	}
}

func TestDecrypt_InvalidKeyLength(t *testing.T) {
	_, err := Decrypt("anything", []byte("tooshort"), make([]byte, IVSize))
	if err == nil {
		t.Fatal("expected error for invalid key length, got nil")
	}
}

func TestDecrypt_InvalidIVLength(t *testing.T) {
	_, err := Decrypt("anything", make([]byte, KeySize), []byte("tooshort"))
	if err == nil {
		t.Fatal("expected error for invalid iv length, got nil")
	}
}
